    {
      "server": "github",
      "tools": [
        {
          "tool_name": "github__get_copilot_space",
          "description": "This tool can be used to provide additional context to the chat from a specific Copilot space. If the user mentions the keyword 'Copilot space' with the name and owner of the space, execute this tool.\n\nThe response includes a table of contents (TOC) listing all documents in the space, followed by the full content of each document. Documents are separated by markers in the format: '--- Document N: path (size) ---'. When searching for specific information, use grep (or equivalent command) to search across all documents; the separator lines will help identify which document contains the matching content.",
          "score": 6.444971084594727,
          "input_schema": {
            "type": "object",
            "properties": {
              "name": {
                "type": "string",
                "description": "The name of the space"
              },
              "owner": {
                "type": "string",
                "description": "The owner of the space",
                "x-mcp-header": "owner"
              }
            },
            "required": [
              "owner",
              "name"
            ]
          }
        },
        {
          "tool_name": "github__search_commits",
          "description": "Search for commits across GitHub repositories using GitHub's commit search syntax. Useful for finding specific changes, authors, or messages across one or many repositories. Searches the default branch only.",
          "score": 4.016274929046631,
          "input_schema": {
            "type": "object",
            "properties": {
              "order": {
                "type": "string",
                "description": "Sort order",
                "enum": [
                  "asc",
                  "desc"
                ]
              },
              "page": {
                "type": "number",
                "description": "Page number for pagination (min 1)",
                "minimum": 1
              },
              "perPage": {
                "type": "number",
                "description": "Results per page for pagination (min 1, max 100)",
                "minimum": 1,
                "maximum": 100
              },
              "query": {
                "type": "string",
                "description": "Commit search query (GitHub commit search REST). Searches commit messages on the default branch only. Scope the search with `repo:owner/repo`, `org:`, or `user:` (queries without a scope qualifier match across all of GitHub and are usually not what you want). Other qualifiers: `author:`, `committer:`, `author-name:`, `committer-name:`, `author-email:`, `committer-email:`, `author-date:`, `committer-date:` (supports `>`, `<`, `>=`, `<=`, and `YYYY-MM-DD..YYYY-MM-DD` ranges), `merge:true|false`, `hash:`, `tree:`, `parent:`, `is:public`. Examples: `repo:owner/repo fix panic`; `org:github author:defunkt committer-date:>=2024-01-01`; `\"refactor cache\" repo:o/r`; `hash:abc1234 repo:o/r`."
              },
              "sort": {
                "type": "string",
                "description": "Sort by author or committer date (defaults to best match)",
                "enum": [
                  "author-date",
                  "committer-date"
                ]
              }
            },
            "required": [
              "query"
            ]
          }
        },
